// kittu-compat:file
// Generated by scripts/rebrand-kittu.mjs; legacy markers are intentional.
import { describe, expect, it } from "vitest";
import {
	hasKittuCommentMarker,
	KITTU_COMMENT_MARKER,
	withKittuCommentMarker,
} from "../src/GitHubCommentService.js";

describe("comment marker compatibility", () => {
	it("recognises both the new and the pre-rebrand marker", () => {
		expect(hasKittuCommentMarker(`hi\n\n${KITTU_COMMENT_MARKER}`)).toBe(true);
		expect(hasKittuCommentMarker("hi\n\n<!-- cyrus-agent -->")).toBe(true);
		expect(hasKittuCommentMarker("plain")).toBe(false);
		expect(hasKittuCommentMarker(null)).toBe(false);
	});

	it("writes only the new marker", () => {
		const out = withKittuCommentMarker("hello");
		expect(out).toContain(KITTU_COMMENT_MARKER);
		expect(out).not.toContain("cyrus");
	});

	it("does not re-mark a body that has the legacy marker", () => {
		const legacy = "hello\n\n<!-- cyrus-agent -->";
		expect(withKittuCommentMarker(legacy)).toBe(legacy);
	});
});
